"""Independent authored geology compositions, revision 8 onward.
Coordinates are composition-specific. No shared rock contour, scattered texture or random placement.
"""
from pathlib import Path
import sys
R=Path(__file__).parent
REV=int(sys.argv[1]) if len(sys.argv)>1 else 16

def p(d,c,op=1):return f'<path d="{d}" fill="{c}" opacity="{op}"/>'
def line(d,c='#96988a',w=1.2,op=.5):return f'<path d="{d}" fill="none" stroke="{c}" stroke-width="{w}" opacity="{op}"/>'
def bed(out,body,lit,side,scar=None):
 if REV>=14:
  from cap_profiles import PROFILES
  lit=PROFILES.get(body.split('L')[0],lit)
 out.append(p(body,'url(#stone)'))
 out.append(p(lit,'url(#lit)'))
 out.append(p(side,'#2d3a3e',.88))
 if scar:out.append(p(scar,'#82908b',.25))

def head(name):return [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 460"><title>{name} — independent bedrock study</title><defs><linearGradient id="stone" x1="0" y1="0" x2=".25" y2="1"><stop stop-color="#596766"/><stop offset=".54" stop-color="#475557"/><stop offset="1" stop-color="#344146"/></linearGradient><linearGradient id="lit" x2=".5" y2="1"><stop stop-color="#899187"/><stop offset=".44" stop-color="#717e78"/><stop offset="1" stop-color="#566766"/></linearGradient><linearGradient id="soil" x2=".3" y2="1"><stop stop-color="#998970"/><stop offset=".4" stop-color="#766d57"/><stop offset="1" stop-color="#4b4d3e"/></linearGradient><linearGradient id="recess" x2=".1" y2="1"><stop stop-color="#16262c"/><stop offset="1" stop-color="#2e3c3f"/></linearGradient></defs>']

