for name,fn in [('shelf',shelf),('shoulder',shoulder),('fan',fan)]:
 content=fn()
 if REV>=9:
  from surface_planes import add_planes
  add_planes(content,name,p)
 if REV>=10:
  from finish import finish
  finish(content,name,p,line,bed)
 if REV>=11:
  from weathering import weather
  weather(content,name,p,line)
 if REV>=14:
  from buried_joints import revise
  revise(content,name,p,line)
 content.append('</svg>')
 svg='\n'.join(content)
 if REV>=11:
  for before,after in {'#596766':'#606967','#475557':'#4c5658','#344146':'#343f43','#899187':'#898e82','#717e78':'#727e74','#566766':'#586861'}.items():svg=svg.replace(before,after)
